//enterprise section homepage
jQuery(document).ready(function($) {
    const observerOptions = { threshold: 0.5 };
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                $('.stat-number').each(function() {
                    const $this = $(this);
                    const countTo = parseInt($this.attr('data-target'));
                    $({ countNum: $this.text() }).animate({ countNum: countTo }, {
                        duration: 2000,
                        easing: 'swing',
                        step: function() { $this.text(Math.floor(this.countNum)); },
                        complete: function() { $this.text(this.countNum); }
                    });
                });
                observer.disconnect();
            }
        });
    }, observerOptions);

    // FIX: Check if the element exists before observing
    const statsGrid = document.querySelector('.enterprise-stats-grid');
    if (statsGrid) {
        observer.observe(statsGrid);
    }

    // FIX: Also wrap your marquee slider to prevent the "Cannot read properties of null" error
    if ($('.enterprise-client-marquee').length > 0) {
        $('.enterprise-client-marquee').slick({
            slidesToShow: 6,
            slidesToScroll: 1,
            autoplay: true,
            autoplaySpeed: 0,
            speed: 8000,
            cssEase: 'linear',
            infinite: true,
            arrows: false,
            dots: false,
            pauseOnHover: false,
            responsive: [
                { breakpoint: 1200, settings: { slidesToShow: 4 } },
                { breakpoint: 768, settings: { slidesToShow: 2 } }
            ]
        });
    }
});


//banner slider homepage
jQuery(document).ready(function($) {
    const $slider = $('.banner-slider-init');
    const slideSpeed = 6000;

    $slider.slick({
        slidesToShow: 1,
        autoplay: true,
        autoplaySpeed: slideSpeed,
        fade: true,
        arrows: false,
        dots: false,
        pauseOnHover: false,
        speed: 1000
    });

    $slider.on('beforeChange', function(e, slick, current, next) {
        $('.nav-label-item').removeClass('active');
        setTimeout(() => {
            $('.nav-label-item[data-slide="' + next + '"]').addClass('active');
        }, 50);
    });

    $('.nav-label-item').on('click', function() {
        $slider.slick('slickGoTo', $(this).data('slide'));
    });

    $('.nav-label-item[data-slide="0"]').addClass('active');
});


//blog-casestudy homepage
jQuery(document).ready(function($) {
    const $slider = $('.resource-init');
    const $container = $('.resource-slider-container');

    const allSlides = $slider.children('.resource-slide').clone();

    const slickSettings = {
        slidesToShow: 3.6,
        infinite: false,
        arrows: false,
        dots: false,
        autoplay: true,
        autoplaySpeed: 2000,
        pauseOnHover: true,
        swipeToSlide: true,
        responsive: [
            { breakpoint: 2800, settings: { slidesToShow: 5.8 } },
            { breakpoint: 2000, settings: { slidesToShow: 4.8 } },
            { breakpoint: 1600, settings: { slidesToShow: 3.8 } },
            { breakpoint: 991, settings: { slidesToShow: 2.3 } },
            { breakpoint: 768, settings: { slidesToShow: 1.2 } }
        ]
    };

    function buildSlider($slides) {
        if ($slider.hasClass('slick-initialized')) {
            $slider.slick('unslick');
        }
        $slider.empty().append($slides);
        $slider.slick(slickSettings);
    }

    buildSlider(allSlides.slice(0, 12).clone());

    $slider.on('afterChange', function(event, slick, currentSlide) {
        if (currentSlide + slick.options.slidesToShow >= slick.slideCount) {
            setTimeout(function() {
                if ($slider.hasClass('slick-initialized')) {
                    $slider.slick('slickGoTo', 0);
                }
            }, 2000);
        }
    });

    $('.resource-filter-item').on('click', function() {
        if ($(this).hasClass('resource-view-all')) {
            return;
        }

        const catId = $(this).data('cat');

        $('.resource-filter-item').removeClass('active');
        $(this).addClass('active');

        $container.addClass('filtering');

        setTimeout(function() {
            const $matched = allSlides.filter('.cat-' + catId).slice(0, 12).clone();
            buildSlider($matched);
            $container.removeClass('filtering');
        }, 400);
    });
});


//service section homepage mobile

window.toggleMobAccordion = function(headerElement) {
    const parentItem = headerElement.parentElement;
    const container = parentItem.parentElement;
    const allItems = container.querySelectorAll('.mobile-accordion-item');
    const isAlreadyActive = parentItem.classList.contains('is-active');

    allItems.forEach(item => {
        item.classList.remove('is-active');
        const icon = item.querySelector('.mob-icon i');
        if (icon) {
            icon.classList.remove('fa-minus');
            icon.classList.add('fa-plus');
        }
    });

    if (!isAlreadyActive) {
        parentItem.classList.add('is-active');
        const icon = parentItem.querySelector('.mob-icon i');
        if (icon) {
            icon.classList.remove('fa-plus');
            icon.classList.add('fa-minus');
        }
    }
};


