//blog faq 

function toggleFaq(element) {
    const item = element.parentElement;
    const isActive = item.classList.contains('active');

    document.querySelectorAll('.experion-blog-faq .faq-item').forEach(el => {
        el.classList.remove('active');
        el.querySelector('.faq-content').style.maxHeight = null;
    });

    if (!isActive) {
        item.classList.add('active');
        const content = item.querySelector('.faq-content');
        content.style.maxHeight = content.scrollHeight + "px";
    }
}


//office locations

(function ($) {
    'use strict';

    var ExpOffices = {

        SLIDE_SPEED:      520,
        AUTOPLAY_MS:      3000,
        REGION_AUTOPLAY:  3000,
        PANEL_OUT_MS:     200,
        PANEL_IN_MS:      320,
        PANEL_DELAY_MS:   140,

        init: function () {
            this.$section = $('.exp-offices');
            if (!this.$section.length) return;

            this.$btns    = this.$section.find('.exp-offices__region-btn');
            this.$markers = this.$section.find('.exp-offices__marker');
            this.$panels  = this.$section.find('.exp-offices__locations');
            this.total    = this.$btns.length;
            this._busy    = false;
            this._regionTimer = null;

            this._initSliders();
            this._bindTabs();
            this._bindArrows();
            this._scheduleNext();

            this.$section.on('mouseenter', function () {
                ExpOffices._stopRegionAutoplay();
            });
            this.$section.on('mouseleave', function () {
                ExpOffices._scheduleNext();
            });
        },

        // Works out how long to wait before moving to next region:
        // if active panel has slick, wait for remaining slides × AUTOPLAY_MS
        // otherwise wait REGION_AUTOPLAY
        _scheduleNext: function () {
            var self = this;
            self._stopRegionAutoplay();

            var $active = self.$panels.filter('.exp-offices__locations--active');
            var $sw     = $active.find('.exp-offices__slider-wrap');

            if ($sw.hasClass('slick-initialized')) {
                // Let slick handle its own autoplay — listen for afterChange
                // _regionTimer will be set when slick hits last slide (see _initSliders)
                $sw.slick('slickPlay');
            } else {
                // Single location — just use region timer
                self._regionTimer = setTimeout(function () {
                    var next = self._activeIdx() + 1;
                    if (next >= self.total) next = 0;
                    self._go(next);
                }, self.REGION_AUTOPLAY);
            }
        },

        _stopRegionAutoplay: function () {
            if (this._regionTimer) {
                clearTimeout(this._regionTimer);
                this._regionTimer = null;
            }
            // Also stop all slick autoplays
            this.$panels.each(function () {
                var $sw = $(this).find('.exp-offices__slider-wrap');
                if ($sw.hasClass('slick-initialized')) {
                    $sw.slick('slickPause');
                }
            });
        },

        _activeIdx: function () {
            return parseInt(this.$btns.filter('.exp-offices__region-btn--active').data('index'), 10) || 0;
        },

        _initSliders: function () {
            var self = this;
            this.$panels.each(function () {
                var $panel = $(this);
                var $sw    = $panel.find('.exp-offices__slider-wrap');
                var count  = $sw.find('.exp-offices__slide').length;
                if (count < 2) return;

                $sw.slick({
                    slidesToShow:   1,
                    slidesToScroll: 1,
                    arrows:         false,
                    dots:           false,
                    autoplay:       false, // We control autoplay manually
                    speed:          self.SLIDE_SPEED,
                    cssEase:        'cubic-bezier(0.4, 0, 0.2, 1)',
                    infinite:       false, // Must be false so we know when last slide is reached
                    pauseOnHover:   false,
                    waitForAnimate: true,
                    adaptiveHeight: false,
                });

                // After each slide change, check if we're on the last slide
                $sw.on('afterChange', function (event, slick, currentSlide) {
                    var last = slick.slideCount - 1;
                    if (currentSlide === last) {
                        // Last slide reached — wait REGION_AUTOPLAY then go to next region
                        self._stopRegionAutoplay();
                        self._regionTimer = setTimeout(function () {
                            var next = self._activeIdx() + 1;
                            if (next >= self.total) next = 0;
                            self._go(next);
                        }, self.REGION_AUTOPLAY);
                    } else {
                        // Not last slide — schedule next slide
                        self._stopRegionAutoplay();
                        self._regionTimer = setTimeout(function () {
                            $sw.slick('slickNext');
                        }, self.AUTOPLAY_MS);
                    }
                });
            });
        },

        _bindTabs: function () {
            var self = this;
            this.$btns.on('click', function () {
                var idx = parseInt($(this).data('index'), 10);
                if (idx === self._activeIdx() || self._busy) return;
                self._stopRegionAutoplay();
                self._go(idx);
            });
        },

        _bindArrows: function () {
            var self = this;

            this.$section.on('click', '.exp-offices__nav-btn--prev', function () {
                if (self._busy) return;
                var $panel = $(this).closest('.exp-offices__locations');
                var $sw    = $panel.find('.exp-offices__slider-wrap');
                if ($sw.hasClass('slick-initialized')) {
                    var cur = $sw.slick('slickCurrentSlide');
                    if (cur > 0) {
                        self._stopRegionAutoplay();
                        $sw.slick('slickPrev');
                        // Re-schedule from current position
                        self._regionTimer = setTimeout(function () {
                            $sw.slick('slickNext');
                        }, self.AUTOPLAY_MS);
                        return;
                    }
                }
                var prev = self._activeIdx() - 1;
                if (prev < 0) prev = self.total - 1;
                self._stopRegionAutoplay();
                self._go(prev);
            });

            this.$section.on('click', '.exp-offices__nav-btn--next', function () {
                if (self._busy) return;
                var $panel = $(this).closest('.exp-offices__locations');
                var $sw    = $panel.find('.exp-offices__slider-wrap');
                if ($sw.hasClass('slick-initialized')) {
                    var cur  = $sw.slick('slickCurrentSlide');
                    var last = $sw.find('.exp-offices__slide').length - 1;
                    if (cur < last) {
                        self._stopRegionAutoplay();
                        $sw.slick('slickNext');
                        return;
                    }
                }
                var next = self._activeIdx() + 1;
                if (next >= self.total) next = 0;
                self._stopRegionAutoplay();
                self._go(next);
            });
        },

        _go: function (idx) {
            var self  = this;
            var $btn  = this.$btns.filter('[data-index="' + idx + '"]');
            if (!$btn.length) return;
            var rid   = $btn.data('region');
            var $prev = this.$panels.filter('.exp-offices__locations--active');
            var $next = this.$panels.filter('[data-region="' + rid + '"]');
            if ($prev.is($next)) return;

            this._busy = true;

            this.$btns.removeClass('exp-offices__region-btn--active').attr('aria-selected', 'false');
            $btn.addClass('exp-offices__region-btn--active').attr('aria-selected', 'true');

            this.$markers.removeClass('exp-offices__marker--active');
            this.$markers.filter('[data-region="' + rid + '"]').addClass('exp-offices__marker--active');

            var prevH = $prev.outerHeight(true) || 0;
            var $wrap = this.$section.find('.exp-offices__locations-wrap');
            $wrap.css({ height: prevH, overflow: 'hidden' });

            $prev.stop(true, true).css({ position: 'absolute', top: 0, left: 0, width: '100%' });

            $prev.animate({ opacity: 0 }, {
                duration: self.PANEL_OUT_MS,
                easing:   'swing',
                complete: function () {
                    $(this).removeClass('exp-offices__locations--active');
                    // Reset prev panel's slick back to slide 0 for next time
                    var $prevSw = $(this).find('.exp-offices__slider-wrap');
                    if ($prevSw.hasClass('slick-initialized')) {
                        $prevSw.slick('slickGoTo', 0, true);
                    }
                }
            });

            setTimeout(function () {
                $next
                    .css({ position: 'relative', opacity: 0 })
                    .addClass('exp-offices__locations--active');

                var nextH = $next.outerHeight(true) || 0;
                $wrap.animate({ height: nextH }, { duration: self.PANEL_IN_MS, easing: 'swing' });

                $next.stop(true, true).animate({ opacity: 1 }, {
                    duration: self.PANEL_IN_MS,
                    easing:   'swing',
                    complete: function () {
                        $(this).css({ opacity: 1 });
                        $wrap.css({ height: '', overflow: '' });
                        self._busy = false;
                        // Schedule next after panel is fully shown
                        self._scheduleNext();
                    }
                });

            }, self.PANEL_DELAY_MS);
        }
    };

    $(document).ready(function () {
        ExpOffices.init();
    });

})(jQuery);

//LEADERSHIP PAGE
//leadership popup
jQuery(document).ready(function($) {
    $('.exp-leadership-cat-item').on('click', function() {
        if($(this).hasClass('active')) return;

        $('.exp-leadership-cat-item').removeClass('active');
        $(this).addClass('active');

        var slug = $(this).data('slug');
        $('.exp-leadership-member-grid').hide();
        $('#grid-' + slug).fadeIn(500).addClass('active').css('display', 'grid');
    });

    $('.exp-mob-acc-header').off('click').on('click', function(e) {
        e.preventDefault();
        e.stopImmediatePropagation();

        var $item = $(this).closest('.exp-mob-acc-item');
        var $body = $item.find('.exp-mob-acc-body');
        var $icon = $(this).find('.exp-acc-icon');

        if($body.is(':visible')) {
            $body.slideUp(300);
            $icon.text('+');
        } else {
            $('.exp-mob-acc-body').slideUp(300);
            $('.exp-acc-icon').text('+');

            $body.slideDown(300);
            $icon.text('-');
        }
    });

    $(document).on('click', '.exp-btn-readmore', function() {
        $('#expModalName').text($(this).data('name'));
        $('#expModalDesig').html($(this).data('desig'));
        $('#expModalBio').html($(this).data('bio'));
        $('#expLeaderModal').fadeIn(300).css('display', 'flex');
        $('body').css('overflow', 'hidden');
    });

    $('.exp-modal-close-btn, .exp-modal-overlay').on('click', function(e) {
        if (e.target !== this && !$(e.target).hasClass('exp-modal-close-btn')) return;
        $('#expLeaderModal').fadeOut(300, function() {
            $('body').css('overflow', 'auto');
        });
    });
});

//scroll top
jQuery(document).ready(function($) {
    $('.exp-leadership-cat-item').on('click', function() {
        var sectionTop = $('.exp-leadership-section').offset().top;
        $('html, body').animate({ scrollTop: sectionTop - 20 }, 300);
    });
    document.querySelectorAll('.exp-mob-acc-item').forEach(function(item) {
        var header = item.querySelector('.exp-mob-acc-header');
        var body   = item.querySelector('.exp-mob-acc-body');
        if (!header || !body) return;
        var obs = new MutationObserver(function() {
            var open = body.offsetHeight > 0 &&
                       getComputedStyle(body).display !== 'none';
            if (open) {
                var grid = body.querySelector('.exp-mob-member-grid');

                if (grid) {
                    grid.style.transition = 'none';
                    grid.style.opacity = '0';
                }

                var scroller = document.scrollingElement || document.documentElement;

                var wanted = scroller.scrollTop +
                             header.getBoundingClientRect().top - 80;

                // don't ask for more scroll than the page actually has
                var maxScroll = scroller.scrollHeight - window.innerHeight;
                var target = Math.min(wanted, maxScroll);

                scroller.scrollTo({ top: target, behavior: 'smooth' });

                if (grid) {
                    setTimeout(function() {
                        grid.style.transition = 'opacity 0.35s ease';
                        grid.style.opacity = '1';
                    }, 400);
                }
            }
        });
        obs.observe(body, { attributes: true, attributeFilter: ['style', 'class'] });
    });
});


//CLIENTS AND PARTNERS PAGE

jQuery(document).ready(function($) {
    const animateCounters = () => {
        $('.counter').each(function() {
            const $this = $(this);
            const countTo = parseInt($this.attr('data-target'));

            $({ countNum: $this.text() }).animate({
                countNum: countTo
            }, {
                duration: 2500,
                easing: 'swing',
                step: function() {
                    $this.text(Math.floor(this.countNum));
                },
                complete: function() {
                    $this.text(this.countNum);
                }
            });
        });
    };

    const observerOptions = {
        threshold: 0.5
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                animateCounters();
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    const target = document.querySelector('.cp-counter-wrapper');
    if (target) {
        observer.observe(target);
    }

    $('.cp-client-slider').slick({
        slidesToShow: 6,
        slidesToScroll: 1,
        autoplay: true,
        autoplaySpeed: 0,
        speed: 5000,
        cssEase: 'linear',
        arrows: false,
        dots: false,
        pauseOnHover: false,
        responsive: [
            {
                breakpoint: 1200,
                settings: { slidesToShow: 5 }
            },
            {
                breakpoint: 992,
                settings: { slidesToShow: 3 }
            },
            {
                breakpoint: 576,
                settings: { slidesToShow: 2 }
            }
        ]
    });
});

//clients lists 
jQuery(document).ready(function($) {
    $('.cl-filter-btn').on('click', function() {
        const $btn = $(this);
        const filter = $btn.attr('data-filter');
        const $grid = $('.cl-grid');
        const $items = $('.cl-item');

        if ($btn.hasClass('active')) return;

        $('.cl-filter-btn').removeClass('active');
        $btn.addClass('active');

        $grid.css('opacity', '0');

        setTimeout(function() {
            $items.hide().removeClass('is-hidden-load');

            if (filter === 'all') {
                $items.slice(0, 36).show();
                if ($items.length > 36) {
                    $('#cl-load-more').show();
                }
            } else {
                $('.' + filter).show();
                $('#cl-load-more').hide();
            }

            $grid.css('opacity', '1');
        }, 300);
    });

    $('#cl-load-more').on('click', function() {
        $('.cl-item:hidden').slice(0, 18).fadeIn(400);
        if ($('.cl-item:hidden').length === 0) {
            $(this).fadeOut();
        }
    });
});

//partners section 
jQuery(document).ready(function($) {
    function switchDesktopTab(element) {
        const target = $(element).data('target');
        if ($(element).hasClass('active')) return;

        $('.tp-nav-item').removeClass('active');
        $(element).addClass('active');
        $('.tp-details-box').removeClass('active').hide();
        $('#' + target).stop(true, true).fadeIn(400).addClass('active');
    }

    $('.tp-nav-item').on('mouseenter', function() {
        if (window.innerWidth >= 992) {
            switchDesktopTab(this);
        }
    });

    $('.tp-nav-item').off('click').on('click', function(e) {
        if (window.innerWidth < 992) {
            e.preventDefault();
            e.stopImmediatePropagation();

            if ($(this).hasClass('active')) {
                $(this).removeClass('active');
                $(this).next('.tp-mobile-content').stop(true, true).slideUp();
            } else {
                $('.tp-nav-item').removeClass('active');
                $('.tp-mobile-content').stop(true, true).slideUp();
                $(this).addClass('active');
                $(this).next('.tp-mobile-content').stop(true, true).slideDown();
            }
        }
    });

    function updateSticky() {
        if (window.innerWidth < 992) {
            $('.tp-content-sticky').css({'position': 'relative', 'top': '0', 'width': 'auto', 'bottom': 'auto'});
            return;
        }

        const windowTop = $(window).scrollTop();
        const row = $('.exp-tp-row');
        const stickyBox = $('.tp-content-sticky');
        const parentCol = $('.exp-tp-sticky-col');

        if(!row.length) return;

        const rowTop = row.offset().top;
        const rowHeight = row.outerHeight();
        const stickyHeight = stickyBox.outerHeight();
        const headerOffset = 150; 
        const stopPoint = rowTop + rowHeight - stickyHeight;
        const parentWidth = parentCol.get(0).getBoundingClientRect().width;

        if (windowTop + headerOffset >= rowTop && windowTop + headerOffset <= stopPoint) {
            stickyBox.css({
                'position': 'fixed',
                'top': headerOffset + 'px',
                'bottom': 'auto',
                'width': parentWidth + 'px',
                'left': parentCol.offset().left + 'px'
            });
