//article js

jQuery(document).ready(function($) {
    var postsPerPage = 5;
    var currentFilter = 'all';
    var currentPage = 1;
    var $cards = $('.newsroom-article-card');

    function updateNewsroomDisplay(animated) {
        var $filteredCards = $cards.filter(function() {
            if (currentFilter === 'all') {
                return true;
            } else {
                return $(this).hasClass('cat-' + currentFilter);
            }
        });

        var totalFiltered = $filteredCards.length;
        var totalPages = Math.ceil(totalFiltered / postsPerPage);

        if (currentPage > totalPages) {
            currentPage = totalPages;
        }
        if (currentPage < 1) {
            currentPage = 1;
        }

        if (totalFiltered === 0) {
            $('.newsroom-no-posts-found').removeClass('d-none');
            $('.newsroom-pagination-row').hide();
        } else {
            $('.newsroom-no-posts-found').addClass('d-none');
            $('.newsroom-pagination-row').show();
        }

        var startIndex = (currentPage - 1) * postsPerPage;
        var endIndex = startIndex + postsPerPage;

        if (animated) {
            $cards.removeClass('fade-in-active');

            setTimeout(function() {
                $cards.removeClass('show-active');

                $filteredCards.each(function(index) {
                    if (index >= startIndex && index < endIndex) {
                        $(this).addClass('show-active');
                    }
                });

                setTimeout(function() {
                    $filteredCards.each(function(index) {
                        if (index >= startIndex && index < endIndex) {
                            $(this).addClass('fade-in-active');
                        }
                    });
                }, 20);
            }, 300);
        } else {
            $cards.removeClass('show-active').removeClass('fade-in-active');
            $filteredCards.each(function(index) {
                if (index >= startIndex && index < endIndex) {
                    $(this).addClass('show-active').addClass('fade-in-active');
                }
            });
        }

        renderCustomPagination(totalPages, currentPage);
    }

    function renderCustomPagination(totalPages, current) {
        var $paginationUl = $('.newsroom-pagination-container .page-numbers');
        $paginationUl.empty();

        if (totalPages <= 1) {
            $('.newsroom-pagination-row').hide();
            return;
        } else {
            $('.newsroom-pagination-row').show();
        }

        if (current > 1) {
            $paginationUl.append('<li><button class="page-link-custom prev-page" type="button"><svg width="8" height="12" viewBox="0 0 8 12" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M6.5 11L1.5 6L6.5 1" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button></li>');
        }

        for (var i = 1; i <= totalPages; i++) {
            if (i === 1 || i === totalPages || (i >= current - 1 && i <= current + 1)) {
                var activeClass = (i === current) ? ' class="active"' : '';
                $paginationUl.append('<li' + activeClass + '><button class="page-link-custom num-page" type="button" data-page="' + i + '">' + i + '</button></li>');
            } else if (i === 2 || i === totalPages - 1) {
                $paginationUl.append('<li><span class="page-dots">...</span></li>');
            }
        }

        if (current < totalPages) {
            $paginationUl.append('<li><button class="page-link-custom next-page" type="button"><svg width="8" height="12" viewBox="0 0 8 12" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M1.5 1L6.5 6L1.5 11" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button></li>');
        }
    }

    $('.newsroom-tab-btn').on('click', function() {
        if ($(this).hasClass('active')) return;

        $('.newsroom-tab-btn').removeClass('active');
        $(this).addClass('active');

        currentFilter = $(this).data('filter');
        currentPage = 1; 

        updateNewsroomDisplay(true);
    });

    $(document).on('click', '.newsroom-pagination-container .num-page', function() {
        var targetPage = parseInt($(this).data('page'));
        if (targetPage === currentPage) return;

        currentPage = targetPage;
        updateNewsroomDisplay(true);

        $('html, body').animate({
            scrollTop: $('.newsroom-articles-section').offset().top - 40
        }, 300);
    });

    $(document).on('click', '.newsroom-pagination-container .prev-page', function() {
        if (currentPage > 1) {
            currentPage--;
            updateNewsroomDisplay(true);
            $('html, body').animate({
                scrollTop: $('.newsroom-articles-section').offset().top - 40
            }, 300);
        }
    });

    $(document).on('click', '.newsroom-pagination-container .next-page', function() {
        var totalFiltered = $cards.filter(function() {
            return currentFilter === 'all' || $(this).hasClass('cat-' + currentFilter);
        }).length;
        var totalPages = Math.ceil(totalFiltered / postsPerPage);

        if (currentPage < totalPages) {
            currentPage++;
            updateNewsroomDisplay(true);
            $('html, body').animate({
                scrollTop: $('.newsroom-articles-section').offset().top - 40
            }, 300);
        }
    });

    updateNewsroomDisplay(false);
});

