jQuery(document).ready(function($) {
    var initialLimit = 6;
    var currentLimit = initialLimit;

    var $grid = $('#experionDiscoverGrid');
    var $cards = $('.experion-discover-card-item');
    var $emptyState = $('#experionDiscoverEmpty');
    var $loadMoreBtn = $('#experionDiscoverLoadMore');
    var $showLessBtn = $('#experionDiscoverShowLess');

    if (!$grid.length) return;

    function filterAndSortEngine() {
        var selectedTopic = $('#experionTopicFilter').val();
        var selectedIndustry = $('#experionIndustryFilter').val();
        var searchVal = ($('#experionPodcastSearch').val() || '').toLowerCase().trim();
        var currentSort = $('#experionSortFilter').val();

        var $matched = $cards.filter(function() {
            var $card = $(this);
            var cardTopics = $card.data('topics') || [];
            var cardIndustries = $card.data('industries') || [];
            var searchField = $card.data('search') || '';

            var matchTopic = !selectedTopic || cardTopics.includes(selectedTopic);
            var matchIndustry = !selectedIndustry || cardIndustries.includes(selectedIndustry);
            var matchSearch = !searchVal || searchField.indexOf(searchVal) !== -1;

            return matchTopic && matchIndustry && matchSearch;
        });

        if (currentSort === 'title') {
            $matched.sort(function(a, b) {
                return $(a).data('title').localeCompare($(b).data('title'));
            });
        } else {
            $matched.sort(function(a, b) {
                return $(b).data('date') - $(a).data('date');
            });
        }

        $grid.append($matched);

        $cards.removeClass('is-visible is-animated');

        if ($matched.length === 0) {
            $emptyState.show();
            $loadMoreBtn.hide();
            $showLessBtn.hide();
            return;
        } else {
            $emptyState.hide();
        }

        $matched.each(function(index) {
            if (index < currentLimit) {
                var $item = $(this);
                $item.addClass('is-visible');
                setTimeout(function() {
                    $item.addClass('is-animated');
                }, index * 40);
            }
        });

        if ($matched.length > currentLimit) {
            $loadMoreBtn.show();
            $showLessBtn.hide();
        } else if (currentLimit > initialLimit) {
            $loadMoreBtn.hide();
            $showLessBtn.show();
        } else {
            $loadMoreBtn.hide();
            $showLessBtn.hide();
        }
    }

    $('#experionTopicFilter, #experionIndustryFilter, #experionSortFilter').on('change', function() {
        currentLimit = initialLimit;
        filterAndSortEngine();
    });

    $('#experionPodcastSearch').on('input', function() {
        currentLimit = initialLimit;
        filterAndSortEngine();
    });

    $loadMoreBtn.on('click', function() {
        currentLimit += 6;
        filterAndSortEngine();
    });

    $showLessBtn.on('click', function() {
        currentLimit = initialLimit;
        filterAndSortEngine();
        $('html, body').animate({
            scrollTop: $(".experion-discover-filter-bar").offset().top - 40
        }, 400);
    });

    function parseDiscoverYoutube(url) {
        if (!url) return '';
        var regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
        var match = url.match(regExp);
        return (match && match[2].length === 11) ? 'https://www.youtube.com/embed/' + match[2] + '?autoplay=1&rel=0' : '';
    }

    var $discoverModal = $('#experionDiscoverModal');
    var $discoverPlayer = $('#experionDiscoverPlayer');

    $(document).on('click', '.experion-discover-video-wrapper', function() {
        var rawUrl = $(this).data('video-url');
        var cleanEmbed = parseDiscoverYoutube(rawUrl);
        if (cleanEmbed) {
            $discoverPlayer.attr('src', cleanEmbed);
            $discoverModal.addClass('is-active');
        }
    });

    $('#experionDiscoverModal .experion-podcast-modal-close-trigger, #experionDiscoverModal .experion-podcast-modal-backdrop').on('click', function() {
        $discoverModal.removeClass('is-active');
        $discoverPlayer.attr('src', '');
    });

    filterAndSortEngine();
});

