//color filling

document.addEventListener("DOMContentLoaded", function() {
    const textContainer = document.getElementById("experionCultureText");
    if (!textContainer) return;

    const textContent = textContainer.textContent.trim();
    const wordsArray = textContent.split(/(\s+)/);

    const fragment = document.createDocumentFragment();

    wordsArray.forEach(chunk => {
        if (chunk.trim() === "") {
            fragment.appendChild(document.createTextNode(chunk));
        } else {
            const span = document.createElement("span");
            span.className = "experion-culture-scroll-word";
            span.textContent = chunk;
            fragment.appendChild(span);
        }
    });

    textContainer.textContent = "";
    textContainer.appendChild(fragment);

    const DOMWords = textContainer.querySelectorAll(".experion-culture-scroll-word");
    const totalWords = DOMWords.length;

    function evaluateTextFill() {
        const containerRect = textContainer.getBoundingClientRect();
        const viewportHeight = window.innerHeight;

        const startTrigger = viewportHeight * 0.80;
        const endTrigger = viewportHeight * 0.35;
        const totalDistance = startTrigger - endTrigger;

        let currentProgress = (startTrigger - containerRect.top) / totalDistance;
        currentProgress = Math.max(0, Math.min(1, currentProgress));

        const wordsToFill = Math.floor(currentProgress * totalWords);

        DOMWords.forEach((wordSpan, index) => {
            if (index < wordsToFill) {
                wordSpan.classList.add("is-revealed");
            } else {
                wordSpan.classList.remove("is-revealed");
            }
        });
    }

    window.addEventListener("scroll", evaluateTextFill, { passive: true });
    window.addEventListener("resize", evaluateTextFill, { passive: true });
    evaluateTextFill();
});


