document.addEventListener('DOMContentLoaded', function () {
    const nav = document.querySelector('.exp-author-pagination-container');
    const grid = document.getElementById('exp-author-posts-grid');
    const posts = document.querySelectorAll('.exp-post-item');
    const scrollTarget = document.getElementById('exp-feed-top');
    const numericContainer = document.querySelector('.exp-author-numeric-buttons');

    if (!nav || posts.length === 0 || !grid || !numericContainer) return;

    const totalPages = parseInt(nav.getAttribute('data-total-pages'));
    let currentPage = 1;

    function renderPaginationNumbers(activePage) {
        numericContainer.innerHTML = '';
        let pages = [];

        // Always lock page 1 at the beginning
        pages.push(1);

        if (activePage <= 2) {
            // Near the start: 1, 2, 3, ..., total
            if (totalPages >= 2 && !pages.includes(2)) pages.push(2);
            if (totalPages >= 3 && !pages.includes(3)) pages.push(3);

            if (totalPages > 4) {
                pages.push('...');
            } else if (totalPages === 4) {
                pages.push(4); 
            }

            if (totalPages >= 4 && !pages.includes(totalPages)) pages.push(totalPages);
        } 
        else if (activePage === 3) {
            // Exactly on Page 3: 1, 2, ..., 4, 5
            if (!pages.includes(2)) pages.push(2);

            if (totalPages > 5) {
                pages.push('...');
            } else if (totalPages === 5) {
                pages.push('...'); // Forces the dots right in the middle for 5 pages total
            }

            if (totalPages >= 4 && !pages.includes(totalPages - 1)) pages.push(totalPages - 1);
            if (totalPages >= 4 && !pages.includes(totalPages)) pages.push(totalPages);
        } 
        else {
            // Near the end (Page 4 or 5): 1, ..., total-2, total-1, total
            pages.push('...');

            let start = totalPages - 2;
            if (start < 2) start = 2;

            for (let i = start; i <= totalPages; i++) {
                if (!pages.includes(i)) pages.push(i);
            }
        }

        // Output loops to DOM safely
        pages.forEach(p => {
            if (p === '...') {
                const span = document.createElement('span');
                span.className = 'exp-author-ellipsis';
                span.textContent = '...';
                numericContainer.appendChild(span);
            } else {
                const btn = document.createElement('button');
                btn.className = 'page-numbers';
                if (p === activePage) btn.classList.add('current');
                btn.setAttribute('data-target', p);
                btn.textContent = p;
                numericContainer.appendChild(btn);
            }
        });
    }

    function showPage(pageNumber) {
        grid.classList.add('exp-fade-out');

        setTimeout(() => {
            posts.forEach(post => {
                if (parseInt(post.getAttribute('data-page')) === pageNumber) {
                    post.style.display = 'block';
                } else {
                    post.style.display = 'none';
                }
            });

            renderPaginationNumbers(pageNumber);

            const prevBtn = nav.querySelector('.page-numbers[data-target="prev"]');
            const nextBtn = nav.querySelector('.page-numbers[data-target="next"]');

            if (pageNumber === 1) {
                prevBtn.classList.add('disabled');
            } else {
                prevBtn.classList.remove('disabled');
            }

            if (pageNumber === totalPages) {
                nextBtn.classList.add('disabled');
            } else {
                nextBtn.classList.remove('disabled');
            }

            currentPage = pageNumber;

            if (scrollTarget) {
                const offset = 120;
                const bodyRect = document.body.getBoundingClientRect().top;
                const elementRect = scrollTarget.getBoundingClientRect().top;
                const elementPosition = elementRect - bodyRect;
                const offsetPosition = elementPosition - offset;

                window.scrollTo({
                    top: offsetPosition,
                    behavior: 'smooth'
                });
            }

            setTimeout(() => {
                grid.classList.remove('exp-fade-out');
            }, 50);

        }, 250); 
    }

    // Initialize first drawing cycle
    renderPaginationNumbers(1);

    nav.addEventListener('click', function (e) {
        const target = e.target.closest('.page-numbers');
        if (!target || target.classList.contains('disabled') || target.classList.contains('current')) return;

        const action = target.getAttribute('data-target');
        let targetPage = currentPage;

        if (action === 'prev') {
            targetPage = currentPage - 1;
        } else if (action === 'next') {
            targetPage = currentPage + 1;
        } else {
            targetPage = parseInt(action);
        }

        if (targetPage >= 1 && targetPage <= totalPages) {
            showPage(targetPage);
        }
    });
});

// CATEGORY PAGE
document.addEventListener('DOMContentLoaded', function () {
    const nav = document.querySelector('.exp-cat-pagination-nav');
    const grid = document.getElementById('exp-cat-posts-grid');
    const posts = document.querySelectorAll('.exp-cat-item');
    const scrollTarget = document.getElementById('exp-cat-top-target');
    const numericContainer = document.querySelector('.exp-cat-numeric-buttons');

    if (!nav || posts.length === 0 || !grid || !numericContainer) return;

    const totalPages = parseInt(nav.getAttribute('data-total-pages'));
    let currentPage = 1;

    function renderPaginationNumbers(activePage) {
        numericContainer.innerHTML = '';
        let pages = [];

        // Always lock page 1 at the beginning
        pages.push(1);

        if (activePage <= 2) {
            // Near the start: 1, 2, 3, ..., total
            if (totalPages >= 2 && !pages.includes(2)) pages.push(2);
            if (totalPages >= 3 && !pages.includes(3)) pages.push(3);

            if (totalPages > 4) {
                pages.push('...');
            } else if (totalPages === 4) {
                pages.push(4); 
            }

            if (totalPages >= 4 && !pages.includes(totalPages)) pages.push(totalPages);
        } 
        else if (activePage === 3) {
            // Exactly on Page 3: 1, 2, ..., 4, 5
            if (!pages.includes(2)) pages.push(2);

            if (totalPages > 5) {
                pages.push('...');
            } else if (totalPages === 5) {
                pages.push('...'); // Forces the dots right in the middle for 5 pages total
            }

            if (totalPages >= 4 && !pages.includes(totalPages - 1)) pages.push(totalPages - 1);
            if (totalPages >= 4 && !pages.includes(totalPages)) pages.push(totalPages);
        } 
        else {
            // Near the end (Page 4 or 5): 1, ..., total-2, total-1, total
            pages.push('...');

            let start = totalPages - 2;
            if (start < 2) start = 2;

            for (let i = start; i <= totalPages; i++) {
                if (!pages.includes(i)) pages.push(i);
            }
        }

        // Output loops to DOM safely
        pages.forEach(p => {
            if (p === '...') {
                const span = document.createElement('span');
                span.className = 'exp-cat-ellipsis';
                span.textContent = '...';
                numericContainer.appendChild(span);
            } else {
                const btn = document.createElement('button');
                btn.className = 'cat-page-btn';
                if (p === activePage) btn.classList.add('current');
                btn.setAttribute('data-target', p);
                btn.textContent = p;
                numericContainer.appendChild(btn);
            }
        });
    }

    function showPage(pageNumber) {
        grid.classList.add('exp-fade-out');

        setTimeout(() => {
            posts.forEach(post => {
                if (parseInt(post.getAttribute('data-page')) === pageNumber) {
                    post.style.display = 'block';
                } else {
                    post.style.display = 'none';
                }
            });

            renderPaginationNumbers(pageNumber);

            const prevBtn = nav.querySelector('.cat-page-btn[data-target="prev"]');
            const nextBtn = nav.querySelector('.cat-page-btn[data-target="next"]');

            if (pageNumber === 1) {
                prevBtn.classList.add('disabled');
            } else {
                prevBtn.classList.remove('disabled');
            }

            if (pageNumber === totalPages) {
                nextBtn.classList.add('disabled');
            } else {
                nextBtn.classList.remove('disabled');
            }

            currentPage = pageNumber;

            if (scrollTarget) {
                const offset = 120;
                const bodyRect = document.body.getBoundingClientRect().top;
                const elementRect = scrollTarget.getBoundingClientRect().top;
                const elementPosition = elementRect - bodyRect;
                const offsetPosition = elementPosition - offset;

                window.scrollTo({
                    top: offsetPosition,
                    behavior: 'smooth'
                });
            }

            setTimeout(() => {
                grid.classList.remove('exp-fade-out');
            }, 50);

        }, 250); 
    }

    // Initialize first drawing cycle
    renderPaginationNumbers(1);

    nav.addEventListener('click', function (e) {
        const target = e.target.closest('.cat-page-btn');
        if (!target || target.classList.contains('disabled') || target.classList.contains('current')) return;

        const action = target.getAttribute('data-target');
        let targetPage = currentPage;

        if (action === 'prev') {
            targetPage = currentPage - 1;
        } else if (action === 'next') {
            targetPage = currentPage + 1;
        } else {
            targetPage = parseInt(action);
        }

        if (targetPage >= 1 && targetPage <= totalPages) {
            showPage(targetPage);
        }
    });
});

