//csr gallery
jQuery(document).ready(function($) {
    if ($('.csr-gallery-slick-slider').length) {
        $('.csr-gallery-slick-slider').slick({
            dots: false,
            arrows: false,
            infinite: true,
            speed: 400,
            slidesToShow: 3,
            slidesToScroll: 1,
            autoplay: true,
            autoplaySpeed: 4000,
            responsive: [
                {
                    breakpoint: 992,
                    settings: {
                        slidesToShow: 2,
                        slidesToScroll: 1
                    }
                },
                {
                    breakpoint: 576,
                    settings: {
                        slidesToShow: 1,
                        slidesToScroll: 1
                    }
                }
            ]
        });
    }

    const lightbox  = document.getElementById('csr-gallery-lightbox');
    const container = document.getElementById('csr-lightbox-media-container');
    const closeBtn  = document.querySelector('.csr-lightbox-close');
    const prevBtn   = document.querySelector('.csr-lightbox-prev');
    const nextBtn   = document.querySelector('.csr-lightbox-next');

    if (!lightbox || !container || !closeBtn) return;

    let mediaItems   = [];
    let currentIndex = 0;

    function buildMediaList() {
        mediaItems = [];
        document.querySelectorAll('.csr-gallery-card:not(.slick-cloned)').forEach(function(card) {
            mediaItems.push({
                src:     card.getAttribute('data-csr-src'),
                isVideo: card.classList.contains('csr-type-video')
            });
        });
    }

    function getYouTubeId(url) {
        var match = url.match(/^.*(youtu\.be\/|v\/|embed\/|watch\?v=|&v=)([^#&?]*).*/);
        return (match && match[2].length === 11) ? match[2] : null;
    }

    function renderMedia(index) {
        var item = mediaItems[index];
        if (!item) return;
        container.innerHTML = '';
        if (item.isVideo) {
            var videoId = getYouTubeId(item.src);
            if (videoId) {
                container.innerHTML = '<iframe src="https://www.youtube.com/embed/' + videoId + '?autoplay=1&rel=0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>';
            }
        } else {
            container.innerHTML = '<img src="' + item.src + '" alt="Gallery Image">';
        }
    }

    function openLightbox(index) {
        currentIndex = index;
        renderMedia(currentIndex);
        lightbox.style.display = 'flex';
        setTimeout(function() {
            lightbox.classList.add('csr-active');
            lightbox.setAttribute('aria-hidden', 'false');
        }, 10);
        document.body.style.overflow = 'hidden';
    }

    function closeLightbox() {
        lightbox.classList.remove('csr-active');
        lightbox.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
        setTimeout(function() {
            lightbox.style.display = 'none';
            container.innerHTML = '';
        }, 300);
    }

    function showPrev() {
        currentIndex = (currentIndex - 1 + mediaItems.length) % mediaItems.length;
        renderMedia(currentIndex);
    }

    function showNext() {
        currentIndex = (currentIndex + 1) % mediaItems.length;
        renderMedia(currentIndex);
    }

    $(document).on('click', '.csr-gallery-card', function() {
        buildMediaList();
        var src = this.getAttribute('data-csr-src');
        var idx = 0;
        for (var i = 0; i < mediaItems.length; i++) {
            if (mediaItems[i].src === src) {
                idx = i;
                break;
            }
        }
        openLightbox(idx);
    });

    prevBtn.addEventListener('click', showPrev);
    nextBtn.addEventListener('click', showNext);
    closeBtn.addEventListener('click', closeLightbox);

    lightbox.addEventListener('click', function(e) {
        if (e.target === lightbox || e.target.classList.contains('csr-lightbox-content')) {
            closeLightbox();
        }
    });

    document.addEventListener('keydown', function(e) {
        if (!lightbox.classList.contains('csr-active')) return;
        if (e.key === 'Escape')     closeLightbox();
        if (e.key === 'ArrowLeft')  showPrev();
        if (e.key === 'ArrowRight') showNext();
    });
});


