//insights
document.addEventListener('DOMContentLoaded', function() {
    const topicBox = document.getElementById('topicFilterBox');
    const industryBox = document.getElementById('industryFilterBox');
    const topicDrawer = document.getElementById('topicDrawer');
    const industryDrawer = document.getElementById('industryDrawer');

    if (!topicBox || !industryBox || !topicDrawer || !industryDrawer) return;

    const topicTriggerLabel = topicBox.querySelector('.trigger-label');
    const industryTriggerLabel = industryBox.querySelector('.trigger-label');

    function closeAllDrawers() {
        topicBox.classList.remove('active');
        industryBox.classList.remove('active');
        topicBox.querySelector('.sign').textContent = '+';
        industryBox.querySelector('.sign').textContent = '+';
        topicDrawer.classList.remove('open');
        industryDrawer.classList.remove('open');
    }

    topicBox.querySelector('.filter-trigger').addEventListener('click', function(e) {
        e.stopPropagation();
        const isOpen = topicDrawer.classList.contains('open');
        closeAllDrawers();
        if(!isOpen) {
            topicBox.classList.add('active');
            topicBox.querySelector('.sign').textContent = '-';
            topicDrawer.classList.add('open');
        }
    });

    industryBox.querySelector('.filter-trigger').addEventListener('click', function(e) {
        e.stopPropagation();
        const isOpen = industryDrawer.classList.contains('open');
        closeAllDrawers();
        if(!isOpen) {
            industryBox.classList.add('active');
            industryBox.querySelector('.sign').textContent = '-';
            industryDrawer.classList.add('open');
        }
    });

    const tagPills = document.querySelectorAll('.insights-page-wrap .tag-pill');
    tagPills.forEach(pill => {
        pill.addEventListener('click', function(e) {
            e.stopPropagation();
            const parentDrawer = this.closest('.filter-expanded-drawer');
            const parentInner = this.closest('.drawer-inner');
            const associatedRadio = this.querySelector('input');

            parentInner.querySelectorAll('.tag-pill').forEach(p => p.classList.remove('active'));
            this.classList.add('active');
            associatedRadio.checked = true;

            const selectedLabel = associatedRadio.getAttribute('data-label');
            if(parentDrawer.id === 'topicDrawer') {
                topicTriggerLabel.textContent = selectedLabel;
            } else if(parentDrawer.id === 'industryDrawer') {
                industryTriggerLabel.textContent = selectedLabel;
            }

            closeAllDrawers();
            filterAndSortInsights();
        });
    });

    const searchInput = document.getElementById('insightsSearch');
    const sortSelect = document.getElementById('insightsSort');
    const loadMoreBtn = document.getElementById('loadMoreBtn');
    const grid = document.getElementById('insightsGrid');
    const emptyState = document.getElementById('insightsEmptyState');
    const emptyStateMessage = document.getElementById('emptyStateMessage');

    const cards = Array.from(grid.querySelectorAll('.insight-card'));

    let visibleCount = 14;
    let filteredCards = [...cards];

    searchInput.addEventListener('input', filterAndSortInsights);
    sortSelect.addEventListener('change', filterAndSortInsights);

    function updateAvailableIndustryPills(selectedTopic) {
        const industryPills = industryDrawer.querySelectorAll('.tag-pill');

        industryPills.forEach(pill => {
            const radio = pill.querySelector('input');
            const industryValue = radio.value;

            if (industryValue === 'all') {
                pill.style.display = 'block';
                return;
            }

            const hasMatchingPosts = cards.some(card => {
                const matchesTopic = (selectedTopic === 'all' || card.getAttribute('data-type') === selectedTopic);
                const cardCats = card.getAttribute('data-categories').split(' ');
                const matchesIndustry = cardCats.includes(industryValue);
                return matchesTopic && matchesIndustry;
            });

            if (hasMatchingPosts) {
                pill.style.display = 'block';
            } else {
                pill.style.display = 'none';
                if (radio.checked) {
                    pill.classList.remove('active');
                    const allPill = industryDrawer.querySelector('input[value="all"]').parentNode;
                    allPill.classList.add('active');
                    industryDrawer.querySelector('input[value="all"]').checked = true;
                    industryTriggerLabel.textContent = 'Topic';
                }
            }
        });
    }

    function filterAndSortInsights() {
        const selectedTopic = document.querySelector('input[name="topic"]:checked').value;

        updateAvailableIndustryPills(selectedTopic);

        const selectedIndustry = document.querySelector('input[name="industry"]:checked').value;
        const searchQuery = searchInput.value.toLowerCase().trim();

        let matched = cards.filter(card => {
            const matchesTopic = (selectedTopic === 'all' || card.getAttribute('data-type') === selectedTopic);

            const cardCats = card.getAttribute('data-categories').split(' ');
            const matchesIndustry = (selectedIndustry === 'all' || cardCats.includes(selectedIndustry));

            const cardTitle = card.getAttribute('data-title').toLowerCase();
            const matchesSearch = (searchQuery === '' || cardTitle.includes(searchQuery) || cardCats.some(c => c.includes(searchQuery)));

            return matchesTopic && matchesIndustry && matchesSearch;
        });

        const sortValue = sortSelect.value;
        if (sortValue === 'name') {
            matched.sort((a, b) => a.getAttribute('data-title').localeCompare(b.getAttribute('data-title')));
            filteredCards = matched;
        } else {
            if (selectedTopic === 'all' && matched.length > 0) {
                const blogs = matched.filter(c => c.getAttribute('data-type') === 'post');
                const caseStudies = matched.filter(c => c.getAttribute('data-type') === 'casestudy');
                const interleaved = [];

                let nextIsBlog = matched[0].getAttribute('data-type') === 'post';

                while (blogs.length > 0 || caseStudies.length > 0) {
                    if (nextIsBlog) {
                        if (blogs.length > 0) interleaved.push(blogs.shift());
                        else interleaved.push(caseStudies.shift());
                    } else {
                        if (caseStudies.length > 0) interleaved.push(caseStudies.shift());
                        else interleaved.push(blogs.shift());
                    }
                    nextIsBlog = !nextIsBlog;
                }
                filteredCards = interleaved;
            } else {
                filteredCards = matched;
            }
        }

        // Prioritize titles that START WITH the search query
        if (searchQuery !== '') {
            const q = searchQuery;
            const startsWith = filteredCards.filter(c => c.getAttribute('data-title').toLowerCase().startsWith(q));
            const others    = filteredCards.filter(c => !c.getAttribute('data-title').toLowerCase().startsWith(q));
            filteredCards = [...startsWith, ...others];
        }

        filteredCards.forEach(card => {
            grid.appendChild(card);
        });

        cards.forEach(card => {
            card.classList.remove('grid-visible', 'animate-up', 'span-col-4', 'span-wide', 'span-narrow');
        });

        if (filteredCards.length === 0) {
            grid.style.display = 'none';
            emptyState.style.display = 'block';
            if (selectedTopic === 'post') {
                emptyStateMessage.textContent = 'No blogs found!';
            } else if (selectedTopic === 'casestudy') {
                emptyStateMessage.textContent = 'No case studies found!';
            } else {
                emptyStateMessage.textContent = 'No insights found!';
            }
        } else {
            grid.style.display = 'grid';
            emptyState.style.display = 'none';
        }

        visibleCount = 14;
        renderGrid();
    }

    function renderGrid() {
        const itemsToDisplay = filteredCards.slice(0, visibleCount);

        let currentItemIndex = 0;
        let isFourCardRow = true;

        itemsToDisplay.forEach(card => {
            card.classList.remove('span-col-4', 'span-wide', 'span-narrow');
        });

        while (currentItemIndex < itemsToDisplay.length) {
            const remainingCount = itemsToDisplay.length - currentItemIndex;

            if (isFourCardRow) {
                const cardsInThisRow = Math.min(4, remainingCount);
                for (let i = 0; i < cardsInThisRow; i++) {
                    const card = itemsToDisplay[currentItemIndex + i];
                    card.classList.add('span-col-4');
                }
                currentItemIndex += cardsInThisRow;
                isFourCardRow = false;
            } else {
                const cardsInThisRow = Math.min(3, remainingCount);

                if (cardsInThisRow === 3) {
                    itemsToDisplay[currentItemIndex].classList.add('span-wide');   
                    itemsToDisplay[currentItemIndex + 1].classList.add('span-narrow'); 
                    itemsToDisplay[currentItemIndex + 2].classList.add('span-wide');   
                } else {
                    for (let i = 0; i < cardsInThisRow; i++) {
                        itemsToDisplay[currentItemIndex + i].classList.add('span-col-4');
                    }
                }
                currentItemIndex += cardsInThisRow;
                isFourCardRow = true;
            }
        }

        itemsToDisplay.forEach((card, index) => {
            card.classList.add('grid-visible');
            setTimeout(() => {
                card.classList.add('animate-up');
            }, index * 30);
        });

        if (visibleCount >= filteredCards.length) {
            loadMoreBtn.style.display = 'none';
        } else {
            loadMoreBtn.style.display = 'inline-flex';
        }
    }

    loadMoreBtn.addEventListener('click', function() {
        visibleCount += 14;
        renderGrid();
    });

    filterAndSortInsights();
});

