document.addEventListener('DOMContentLoaded', function () {
    const dataSet = window.resourceData || [];
    const tabs = document.querySelectorAll('.resource-page-wrap .res-tab-trigger');
    const paneBox = document.querySelector('.resource-page-wrap .res-pane-box');
    const descPane = document.querySelector('.resource-page-wrap .res-pane-description');
