    tabs.forEach(tab => {
        tab.addEventListener('click', function () {
            if (this.classList.contains('active')) return;

            tabs.forEach(t => t.classList.remove('active'));
            this.classList.add('active');

            paneBox.classList.add('res-fade-out');

            setTimeout(() => {
                const index = this.getAttribute('data-target');
                const item = dataSet[index];

                if (item) {
                    descPane.innerHTML = item.content;

                    if (item.link) {
                        actionLink.setAttribute('href', item.link);
                        linkContainer.style.display = 'block';
                    } else {
                        linkContainer.style.display = 'none';
                    }

                    pillsContainer.innerHTML = '';
                    if (item.points && item.points.length > 0) {
                        item.points.forEach(pt => {
                            const a = document.createElement('a');
                            a.href = pt.link;
                            a.className = 'res-pill-item';
                            a.textContent = pt.text;
                            pillsContainer.appendChild(a);
                        });
                    }
                }

                paneBox.classList.remove('res-fade-out');
            }, 250);
        });
    });

    // --- Mobile: set real height on the first (open) item so it animates correctly ---
    const firstOpen = document.querySelector('.resource-page-wrap .res-acc-item.active .res-acc-content');
    if (firstOpen) firstOpen.style.maxHeight = firstOpen.scrollHeight + 'px';

    // --- Mobile: accordion ---
    const accHeaders = document.querySelectorAll('.resource-page-wrap .res-acc-header');
    accHeaders.forEach(header => {
        header.addEventListener('click', function () {
            const currentItem = this.parentElement;
            const currentContent = this.nextElementSibling;
            const isNowActive = currentItem.classList.contains('active');

            // Header's position before anything collapses
            const headerTopBefore = currentItem.getBoundingClientRect().top + window.pageYOffset;

            // If an open item sits ABOVE this one, it will collapse and shift us up.
            // Measure how much height we'll lose so we can correct for it.
            let heightAbove = 0;
            const activeItem = document.querySelector('.resource-page-wrap .res-acc-item.active');
            if (activeItem && activeItem !== currentItem) {
                if (activeItem.getBoundingClientRect().top < currentItem.getBoundingClientRect().top) {
                    heightAbove = activeItem.querySelector('.res-acc-content').offsetHeight;
                }
            }

            // Close all
            document.querySelectorAll('.resource-page-wrap .res-acc-item').forEach(item => {
                item.classList.remove('active');
                item.querySelector('.res-acc-content').style.maxHeight = '0px';
            });

            // Open the clicked one (if it wasn't already open)
            if (!isNowActive) {
                currentItem.classList.add('active');
                currentContent.style.maxHeight = currentContent.scrollHeight + 'px';

                const offset = 20; // small gap above the header
                const target = Math.max(0, headerTopBefore - heightAbove - offset);
                window.scrollTo({ top: target, behavior: 'smooth' });
            }
        });
    });
});

