document.addEventListener('DOMContentLoaded', function () {
    const counters = document.querySelectorAll('.ind-animate-num');

    const countUp = (targetEl) => {
        const target = parseFloat(targetEl.getAttribute('data-target')) || 0;
        const suffix = targetEl.getAttribute('data-suffix') || '';
        const duration = 2000;
        const startTime = performance.now();

        const updateNumber = (currentTime) => {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);

            const easeOutQuad = progress * (2 - progress);
            const currentValue = Math.floor(easeOutQuad * target);

            targetEl.textContent = currentValue.toLocaleString('en-US') + suffix;

            if (progress < 1) {
                requestAnimationFrame(updateNumber);
            } else {
                targetEl.textContent = target.toLocaleString('en-US') + suffix;
            }
        };

        requestAnimationFrame(updateNumber);
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                countUp(entry.target);
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.2 });

    counters.forEach(counter => observer.observe(counter));
});

