//careers listing
jQuery(document).ready(function($) {
    var postsPerPage = 5;
    var currentVisible = postsPerPage;

    if (!$('.career-job-row').length) return;

    function applyPaginationAndFilters(animate) {
        var searchVal = ($('#career-search-input').val() || '').toLowerCase();
        var expRange = $('#filter-experience').val();
        var locVal = ($('#filter-location').val() || '').toLowerCase();

        var matchCount = 0;
        var speed = animate ? 350 : 0;

        $('.career-job-row').each(function() {
            var $row = $(this);
            var title = $row.find('.career-job-title').text().toLowerCase();
            var jobExpText = $row.attr('data-exp') || '';
            var jobLocText = ($row.attr('data-loc') || '').toLowerCase();

            var jobExpNum = parseInt(jobExpText.replace(/[^0-9]/g, ''), 10);

            var matchSearch = title.includes(searchVal);
            var matchLoc = locVal === "" || jobLocText.includes(locVal);
            var matchExp = true;

            if (expRange !== "") {
                var range = expRange.split('-');
                var min = parseInt(range[0], 10);
                var max = parseInt(range[1], 10);

                if (!isNaN(jobExpNum)) {
                    matchExp = (jobExpNum >= min && jobExpNum <= max);
                } else {
                    matchExp = false;
                }
            }

            var shouldShow = false;
            if (matchSearch && matchLoc && matchExp) {
                matchCount++;
                if (matchCount <= currentVisible) {
                    shouldShow = true;
                }
            }

            if (shouldShow) {
                if ($row.css('display') === 'none') {
                    $row.stop(true, true).css({ display: 'flex', opacity: 0 }).animate({ opacity: 1 }, speed);
                } else {
                    $row.stop(true, true).css('opacity', 1);
                }
            } else {
                if ($row.css('display') !== 'none') {
                    $row.stop(true, true).animate({ opacity: 0 }, speed, function() {
                        $(this).css('display', 'none');
                    });
                }
            }
        });

        if (matchCount <= currentVisible) {
            $('.career-load-more-wrap').fadeOut(400);
        } else {
            $('.career-load-more-wrap').fadeIn(400);
        }

        $('.career-no-results').remove();
        if (matchCount === 0) {
            $('.career-jobs-container').after('<p class="career-no-results no-jobs-found">No job positions found matching your criteria.</p>');
        }
    }

    $('#load-more-jobs').on('click', function(e) {
        e.preventDefault();
        currentVisible += postsPerPage;
        applyPaginationAndFilters(true);
    });

    $('#career-search-input').on('keyup input', function() {
        currentVisible = postsPerPage;
        applyPaginationAndFilters(false);
    });

    $('#filter-experience, #filter-location').on('change', function() {
        currentVisible = postsPerPage;
        applyPaginationAndFilters(true);
    });

    $('#filter-sort').on('change', function() {
        var $container = $('.career-jobs-container');
        $container.stop(true, true).animate({ opacity: 0 }, 250, function() {
            var $rows = $container.children('.career-job-row').get();
            $rows.reverse();
            $.each($rows, function(index, row) {
                $container.append(row);
            });
            currentVisible = postsPerPage;
            applyPaginationAndFilters(false);
            $container.animate({ opacity: 1 }, 250);
        });
    });

    applyPaginationAndFilters(false);
});


